"""Splitting money between parties."""

from collections.abc import Sequence


def _plain_split(total: int, weights: Sequence[int]) -> list[int]:
    """Split `total` by `weights`, rounding down and handing out leftover cents by largest remainder."""
    weight_sum = sum(weights)
    shares = [total * w // weight_sum for w in weights]
    leftover = total - sum(shares)
    remainders = [total * w % weight_sum for w in weights]
    order = sorted(range(len(weights)), key=lambda i: (-remainders[i], i))
    for i in order[:leftover]:
        shares[i] += 1
    return shares


def allocate(total: int, weights: Sequence[int], caps: Sequence[int] | None = None) -> list[int]:
    """Split `total` cents in proportion to `weights`. See README.md for the rules."""
    if total < 0:
        raise ValueError("total must not be negative")
    if len(weights) == 0:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must not be negative")
    if sum(weights) == 0:
        raise ValueError("weights must not all be zero")
    if caps is not None:
        if len(caps) != len(weights):
            raise ValueError("caps must have one entry per weight")
        if any(c < 0 for c in caps):
            raise ValueError("caps must not be negative")
        capacity = sum(c for c, w in zip(caps, weights) if w > 0)
        if capacity < total:
            raise ValueError("caps cannot hold the total")

    n = len(weights)
    if caps is None:
        return _plain_split(total, list(weights))

    result = [0] * n
    fixed = [w == 0 for w in weights]
    while True:
        remaining = total - sum(result)
        active = [i for i in range(n) if not fixed[i]]
        shares = _plain_split(remaining, [weights[i] if not fixed[i] else 0 for i in range(n)])
        over = [i for i in active if shares[i] > caps[i]]
        if not over:
            for i in active:
                result[i] = shares[i]
            return result
        for i in over:
            result[i] = caps[i]
            fixed[i] = True
